mapper.update:
UPDATE sync_notifications
   SET status = #{status}, handled_at = now()
 WHERE notification_id = #{notificationId}
   AND recipient_id = #{userId}
   AND status = 'pending'

UPDATE sync_notifications
   SET status = #{status}, handled_at = now()
 WHERE recipient_id = #{userId}
   AND team_id = #{teamId}
   AND status = 'pending'

mapper.select:
SELECT COUNT(*)
  FROM personal_places p
 WHERE p.user_id = #{userId}
   AND (p.kakao_place_id = #{kakaoPlaceId,jdbcType=VARCHAR}
        OR (lower(replace(p.name, ' ', '')) = lower(replace(#{name}, ' ', ''))
            AND  < 50))

mapper.delete:
DELETE FROM personal_places p
 WHERE p.user_id = #{userId}
   AND (p.kakao_place_id = #{kakaoPlaceId,jdbcType=VARCHAR}
        OR (lower(replace(p.name, ' ', '')) = lower(replace(#{name}, ' ', ''))
            AND  < 50))
